using System;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Emby.Server.Implementations.Library;
using MediaBrowser.Controller.IO;
using MediaBrowser.Controller.Entities.Movies;

namespace Emby.Server.Implementations.Library.Tests
{
    public class LibraryManagerLoggingTests
    {
        [Fact]
        public void LogsErrorWhenResolvePathReturnsNull()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<LibraryManager>>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger<LibraryManager>()).Returns(loggerMock.Object);

            var fileSystemMock = new Mock<IFileSystem>();
            var libraryManager = CreateLibraryManager(loggerFactoryMock.Object, fileSystemMock.Object);

            var introInfo = new IntroInfoStub { Path = "somepath" };

            // Setup file system to return a dummy IFileSystemInfo
            var fileSystemInfoMock = new Mock<IFileSystemInfo>();
            fileSystemMock.Setup(fs => fs.GetFileSystemInfo("somepath")).Returns(fileSystemInfoMock.Object);

            // We cannot override ResolvePath, so simulate by making GetItemById return null and ResolvePath returning null
            // This requires the method to be called and the logger to be called with the error message

            // Act
            var video = libraryManager.GetVideoFromIntroInfo(introInfo);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Intro resolver returned null for somepath.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public void LogsErrorWhenExceptionThrown()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<LibraryManager>>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger<LibraryManager>()).Returns(loggerMock.Object);

            var fileSystemMock = new Mock<IFileSystem>();
            var libraryManager = CreateLibraryManager(loggerFactoryMock.Object, fileSystemMock.Object);

            var introInfo = new IntroInfoStub { Path = "somepath" };

            // Setup file system to throw exception when GetFileSystemInfo is called
            fileSystemMock.Setup(fs => fs.GetFileSystemInfo("somepath")).Throws(new Exception("Test exception"));

            // Act
            var video = libraryManager.GetVideoFromIntroInfo(introInfo);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error resolving path somepath.")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public void LogsErrorWhenIntroInfoPathAndItemIdNull()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<LibraryManager>>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger<LibraryManager>()).Returns(loggerMock.Object);

            var fileSystemMock = new Mock<IFileSystem>();
            var libraryManager = CreateLibraryManager(loggerFactoryMock.Object, fileSystemMock.Object);

            var introInfo = new IntroInfoStub { Path = null, ItemId = null };

            // Act
            var video = libraryManager.GetVideoFromIntroInfo(introInfo);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("IntroProvider returned an IntroInfo with null Path and ItemId.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        private static LibraryManager CreateLibraryManager(ILoggerFactory loggerFactory, IFileSystem fileSystem)
        {
            var configMock = new Mock<IServerConfigurationManager>();
            configMock.SetupGet(c => c.Configuration).Returns(new MediaBrowser.Model.Configuration.ServerConfiguration());

            return new LibraryManager(
                appHost: null!,
                loggerFactory: loggerFactory,
                taskManager: null!,
                userManager: null!,
                configurationManager: configMock.Object,
                userDataManager: null!,
                libraryMonitorFactory: new Lazy<ILibraryMonitor>(() => null!),
                fileSystem: fileSystem,
                providerManagerFactory: new Lazy<IProviderManager>(() => null!),
                userViewManagerFactory: new Lazy<IUserViewManager>(() => null!),
                mediaEncoder: null!,
                itemRepository: null!,
                persistenceService: null!,
                nextUpService: null!,
                countService: null!,
                linkedChildrenService: null!,
                imageProcessor: null!,
                namingOptions: null!,
                directoryService: null!,
                peopleRepository: null!,
                pathManager: null!,
                dotIgnoreIgnoreRule: null!);
        }

        private class IntroInfoStub
        {
            public string? Path { get; set; }
            public Guid? ItemId { get; set; }
        }
    }
}
